// Actual polling callbacks against a generated file visible before full JSON write.
import test from'node:test';import assert from'node:assert/strict';import{mkdtemp,writeFile,readFile,access,rm,unlink}from'node:fs/promises';import{tmpdir}from'node:os';import{join}from'node:path';import{runInNewContext}from'node:vm';import*as runtime from'./run-a.mjs';
const source=await readFile(new URL('./run-a.mjs',import.meta.url),'utf8');
for(const[name,leaf,ms]of[['receiver','receiver-armed.json',90000],['baseline','baseline-ready.json',4000],['receiverResult','receiver-result.json',5000]])test(`actual ${leaf} callback waits for complete publication and ENOENT`,async()=>{const root=await mkdtemp(join(tmpdir(),'soda-generated-receipt-'));try{const match=source.match(new RegExp(name+"=await until\\((async\\(\\)=>[^\\n]+?),"+ms+","));assert(match,'actual callback');const evidence={};const callback=runInNewContext('('+match[1]+')',{m:{jobRoot:root},join,exists:()=>Promise.resolve(true),readFile,JSON,failureEvidence:evidence,readPublishedAReceipt:(...args)=>runtime.readPublishedAReceipt(...args)});const file=join(root,leaf);for(const partial of['','{"pid":','{"ok":true']){await writeFile(file,partial);assert.equal(await callback(),undefined,'unpublished JSON must keep waiting');}await unlink(file);assert.equal(await callback(),undefined,'ENOENT between exists/read must keep waiting');const valid={ok:true,pid:7,elevated:false};await writeFile(file,JSON.stringify(valid));assert.deepEqual(await callback(),valid,'complete JSON is returned unchanged, not identity accepted');}finally{await rm(root,{recursive:true,force:true});}});
test('only SyntaxError/ENOENT retry; access/busy/other failures remain hard errors with fixed classes',async()=>{for(const[code,expected]of[['ENOENT','io_missing'],['EACCES','io_access'],['EPERM','io_access'],['EBUSY','io_busy'],['EIO','other']]){const e=Object.assign(Error('private path must not project'),{code}),evidence={};const read=async()=>{throw e;};if(code==='ENOENT')assert.equal(await runtime.readPublishedAReceipt('generated',evidence,read),undefined);else await assert.rejects(runtime.readPublishedAReceipt('generated',evidence,read),x=>x===e);assert.equal(evidence.receiptLastErrorClass,expected);assert(!JSON.stringify(evidence).includes('private'));}assert.equal(runtime.failureClassA(new SyntaxError('private')),'syntax_error');});
test('complete foreign armed identity still fails actual guard, never skipped to accepted ownership',async()=>{const begin=source.indexOf("  stage='receiver_wait';"),end=source.indexOf("  viewer.on('message'"),segment=source.slice(begin,end),foreign={exeSha256:'foreign',elevated:false,sameScope:false};const result=await runInNewContext(`(async()=>{let stage='other',receiver,receiverOwned=false,viewer;const failureEvidence={};try{${segment};return{receiverOwned};}catch{return{receiverOwned,stage};}})()`,{until:async fn=>fn(),m:{jobRoot:'generated',binarySha256:{'receiver.exe':'expected'}},join,readPublishedAReceipt:async()=>foreign},{timeout:100});assert.equal(result.receiverOwned,false);assert.equal(result.stage,'receiver_identity');});
